async function savePoint(type,label,speed){if(!state.pos||!type)return;const payload={external_id:`community-${type.toLowerCase()}-${Date.now()}-${state.pos.lat.toFixed(5)}-${state.pos.lon.toFixed(5)}`,latitude:state.pos.lat,longitude:state.pos.lon,velocidade:speed||null,tipo:type};try{const r=await fetch(`${API}radars.php?action=save`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':window.MRA?.csrf||''},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Não foi possível salvar');showRoadAlert(pointKind(payload),'ENVIADO PARA ANÁLISE',j.message||'O ponto será ativado após validação.','Ponto enviado para validação.',3600)}catch(e){showRoadAlert('danger','NÃO FOI POSSÍVEL SALVAR',e.message||'Tente novamente.','',4000)}finally{closePointModal()}}

// ---------- música ----------
const audio=$('#webAudio');
function isDriveTrack(t){return String(t?.origin||'').trim().toLowerCase()==='google drive'}
function trackSource(t){let src=String(t?.source||t?.content_uri||'').trim();if(!src&&isDriveTrack(t)){const id=String(t?.origin_ref||'').trim();if(id&&!/^https?:/i.test(id))src=`${API}drive_stream.php?id=${encodeURIComponent(id)}`}if(!src&&t?.url)src=String(t.url);if(!src&&/^https?:/i.test(String(t?.origin_ref||'')))src=String(t.origin_ref);if(src&&(/^\.\.\//.test(src)||/^\//.test(src)||!/^[a-z]+:/i.test(src)))try{src=new URL(src,location.href).href}catch(_){ }return src}
function normalizeTrack(t){return{...t,id:String(t.id??t.origin_ref??Math.random()),title:String(t.title||'Sem título'),artist:String(t.artist||'Artista desconhecido'),source:trackSource(t)}}
function updatePlayerUi(){const t=state.currentTrack,title=t?.title||'Nenhuma música',artist=t?.artist||'MusicRoad Auto';['boardNowTitle','nowTitle','footerTrackTitle'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=title});['boardNowArtist','nowArtist','footerTrackArtist'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=artist});$$('[data-player="toggle"]').forEach(b=>b.textContent=state.playing?'⏸':'▶');$$('.track-row').forEach((e,i)=>e.classList.toggle('playing',state.filteredTracks[i]&&t&&String(state.filteredTracks[i].id)===String(t.id)))}
async function markPlayed(t){const id=Number(t?.id);if(!Number.isFinite(id)||id<=0)return;fetch(`${API}library.php?action=played`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':window.MRA?.csrf||''},body:JSON.stringify({id})}).catch(()=>{})}
function playTrackByObject(t,autoplay=true){t=normalizeTrack(t);if(!t.source){toastStatus('Esta faixa não possui fonte de áudio reproduzível','MÚSICA');return}state.currentTrack=t;state.trackIndex=state.tracks.findIndex(x=>String(x.id)===String(t.id));try{if(window.MusicRoadAndroid?.playQueue){const queue=state.tracks.map(normalizeTrack).filter(x=>x.source),idx=Math.max(0,queue.findIndex(x=>String(x.id)===String(t.id)));window.MusicRoadAndroid.playQueue(JSON.stringify(queue),idx);state.playing=autoplay;updatePlayerUi();markPlayed(t);return}}catch(_){ }audio.src=t.source;audio.load();if(autoplay)audio.play().catch(()=>toastStatus('O navegador não conseguiu reproduzir esta música','MÚSICA'));updatePlayerUi()}
function togglePlayer(){try{if(window.MusicRoadAndroid?.togglePlay){window.MusicRoadAndroid.togglePlay();state.playing=!state.playing;updatePlayerUi();return}}catch(_){ }if(!audio.src){if(state.tracks.length)playTrackByObject(state.tracks[0]);return}if(audio.paused)audio.play().catch(()=>{});else audio.pause()}
function nextTrack(dir=1){if(!state.tracks.length)return;let i=state.trackIndex;if(i<0)i=0;i=(i+dir+state.tracks.length)%state.tracks.length;playTrackByObject(state.tracks[i])}
$$('[data-player="toggle"]').forEach(b=>b.addEventListener('click',togglePlayer));$$('[data-player="next"]').forEach(b=>b.addEventListener('click',()=>nextTrack(1)));$$('[data-player="prev"]').forEach(b=>b.addEventListener('click',()=>nextTrack(-1)));audio.addEventListener('play',()=>{state.playing=true;updatePlayerUi();markPlayed(state.currentTrack)});audio.addEventListener('pause',()=>{state.playing=false;updatePlayerUi()});audio.addEventListener('ended',()=>nextTrack(1));audio.addEventListener('timeupdate',()=>{if(audio.duration)$('#playerProgress').value=(audio.currentTime/audio.duration)*100});$('#playerProgress')?.addEventListener('input',()=>{if(audio.duration)audio.currentTime=audio.duration*(Number($('#playerProgress').value)/100)});
async function getNativeLibrary(){const bridge=window.MusicRoadAndroid;if(!bridge)return null;if(typeof bridge.scanMusicLibraryAsync==='function')return new Promise(resolve=>{let done=false;const finish=data=>{if(done)return;done=true;clearTimeout(timer);document.removeEventListener('mr:native-library',onData);resolve(data||null)},onData=e=>finish(e.detail);document.addEventListener('mr:native-library',onData,{once:true});const timer=setTimeout(()=>finish(null),12000);try{bridge.scanMusicLibraryAsync()}catch(_){finish(null)}});if(typeof bridge.getMusicLibrary==='function'){try{return JSON.parse(bridge.getMusicLibrary()||'{}')}catch(_){return null}}return null}
async function loadMusic(){let serverTracks=[];try{$('#musicStatus').textContent='Carregando biblioteca…';const r=await fetch(`${API}library.php?action=list`,{cache:'no-store'}),j=await r.json();if(r.ok&&j.ok)serverTracks=j.tracks||[]}catch(_){ }let nativeTracks=[];if(window.MusicRoadAndroid){try{const data=await getNativeLibrary();if(data?.ok)nativeTracks=data.tracks||[];else if(data?.permission==='required'&&typeof window.MusicRoadAndroid.requestAudioPermission==='function')window.MusicRoadAndroid.requestAudioPermission()}catch(_){ }}const seen=new Set();state.tracks=[...nativeTracks,...serverTracks].map(normalizeTrack).filter(t=>{const k=String(t.id)+'|'+t.title+'|'+t.artist;if(seen.has(k))return false;seen.add(k);return true});renderTracks();if(state.tracks.length){const local=nativeTracks.length;$('#musicStatus').textContent=local?`${local} do aparelho · ${serverTracks.length} do servidor/Drive`:'Biblioteca do MusicRoad'}else $('#musicStatus').textContent='Biblioteca vazia ou permissão de músicas necessária'}
function renderTracks(){const q=String($('#musicSearch')?.value||'').trim().toLowerCase();state.filteredTracks=state.tracks.filter(t=>!q||[t.title,t.artist,t.album,t.origin].join(' ').toLowerCase().includes(q));$('#trackCount').textContent=`${state.filteredTracks.length} faixa${state.filteredTracks.length===1?'':'s'}`;const el=$('#tracks');if(!state.filteredTracks.length){el.innerHTML='<div class="empty-state">Nenhuma música encontrada na biblioteca.</div>';return}el.innerHTML=state.filteredTracks.map((t,i)=>`<div class="track-row"><span class="track-index">${i+1}</span><div class="track-meta"><b>${esc(t.title)}</b><span>${esc(t.artist||t.album||t.origin||'MusicRoad')}</span></div><button type="button" data-track-id="${esc(t.id)}">▶</button></div>`).join('');$$('[data-track-id]').forEach(b=>b.addEventListener('click',()=>{const t=state.tracks.find(x=>String(x.id)===String(b.dataset.trackId));if(t)playTrackByObject(t)}));updatePlayerUi()}
$('#reloadMusic')?.addEventListener('click',loadMusic);$('#musicSearch')?.addEventListener('input',renderTracks);
window.mrAutoPlayerState=data=>{if(!data)return;state.playing=!!data.playing;if(data.title){state.currentTrack={...(state.currentTrack||{}),title:data.title,artist:data.artist||''}}updatePlayerUi()};

// ---------- rádio ----------
const RADIO_KEY='mr:radio:stations:v1';
function loadStations(){try{return JSON.parse(localStorage.getItem(RADIO_KEY)||'[]').filter(x=>x&&x.name&&x.url)}catch(_){return[]}}
function saveStations(list){try{localStorage.setItem(RADIO_KEY,JSON.stringify(list))}catch(_){ }renderStations()}
function renderStations(){const box=$('#radioStations');if(!box)return;const list=loadStations();if(!list.length){box.innerHTML='<div class="radio-empty"><span>FM</span><b>Nenhuma rádio online salva</b><small>Adicione nome, frequência e URL direta do stream.</small></div>';return}box.innerHTML=list.map((r,i)=>`<article class="radio-station"><button class="radio-play" data-radio-play="${i}" type="button">▶</button><div><b>${esc(r.name)}</b><span>${esc(r.frequency||'Rádio online')}</span></div><button class="radio-remove" data-radio-remove="${i}" type="button">×</button></article>`).join('');box.querySelectorAll('[data-radio-play]').forEach(b=>b.addEventListener('click',()=>{const r=list[Number(b.dataset.radioPlay)];if(!r)return;playTrackByObject({id:`radio-${Date.now()}`,title:r.name,artist:r.frequency||'Rádio online',origin:'Rádio',source:r.url});$('#radioStatus').textContent=`Tocando ${r.name}${r.frequency?' · '+r.frequency:''}`}));box.querySelectorAll('[data-radio-remove]').forEach(b=>b.addEventListener('click',()=>{list.splice(Number(b.dataset.radioRemove),1);saveStations(list)}))}
$('#radioStationForm')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#radioName').value.trim(),frequency=$('#radioFrequency').value.trim(),url=$('#radioUrl').value.trim();let secure=false;try{secure=new URL(url).protocol==='https:'}catch(_){}if(!secure){$('#radioStatus').textContent='Use uma URL HTTPS direta do stream de áudio.';return}const list=loadStations();list.push({name,frequency,url});saveStations(list);e.currentTarget.reset();$('#radioStatus').textContent=`${name} salva ✓`});
function updateFmStatus(){const st=$('#fmRadioStatus');if(!st)return;if(!window.MusicRoadAndroid?.getFmRadioStatus){st.textContent='FM físico funciona no APK quando o aparelho expõe um aplicativo de rádio.';return}try{const x=JSON.parse(window.MusicRoadAndroid.getFmRadioStatus()||'{}');st.textContent=x.available?`Rádio FM encontrado: ${x.label||'aplicativo do aparelho'}.`:'Nenhum rádio FM exposto pelo aparelho. Use rádios online.'}catch(_){st.textContent='Não foi possível verificar o rádio FM.'}}
function openFm(){if(window.MusicRoadAndroid?.openFmRadioApp){try{const ok=window.MusicRoadAndroid.openFmRadioApp();if(!ok)$('#fmRadioStatus').textContent='Nenhum aplicativo FM compatível foi encontrado.';return}catch(_){ }}$('#fmRadioStatus').textContent='O rádio FM depende do hardware e aplicativo do aparelho.'}
$('#openFmRadio')?.addEventListener('click',openFm);$('#openFmRadioCard')?.addEventListener('click',openFm);renderStations();setTimeout(updateFmStatus,700);

